// assets/skyupLogo.js — Skyup Digital Solutions' real logo (from skyup_logo1.svg):
// the infinity-arrow mark with "SKYUP / Digital Solutions" beside it, as on the
// printed voucher book. Embedded as a data URI because printouts open in a new
// window, where linked image files don't load reliably.
export const SKYUP_LOGO = "data:image/png;base64,";

const SKYUP_GSTIN = "29AFUFS6710E1ZJ";
// True for Skyup's own company record (other companies keep their own logo).
export const isSkyupCompany = (co = {}) =>
  String(co.gstin || "").toUpperCase().replace(/\s/g, "") === SKYUP_GSTIN || /\bsky\s*up\s+digital\b/i.test(String(co.name || ""));
